"""Inventory exact native foreground reservations over the bank without transferring ownership."""
import json,hashlib
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
R=Path(__file__).resolve().parents[3];B=R/'level-editor/work/croisement03-refinement';O=B/'restart2/bank-foreground-source-audit-v2'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 assert not O.exists();O.mkdir();lp=B/'baseline/Croisement03.rhp.json';ip=B/'source-inventory.json';sp=B/'baseline/covered.png';level=json.loads(lp.read_text());inventory=json.loads(ip.read_text());src=Image.open(sp).convert('RGB');pins={str(p):sha(p)for p in [lp,ip,sp]}
 def mask(i):
  path=B/f'baseline/masks/{i:06}.png';pins[str(path)]=sha(path);im=Image.new('L',src.size);im.paste(Image.open(path),tuple(level['masks'][i]['box_top_left']));return np.array(im)>0
 bank=mask(96)|mask(108)|mask(109);occupancy=mask(120)|mask(121);wood=mask(18);animation=next(a for a in inventory['animations']if a['profile']=='Croisement03 - Arbre05');union=np.zeros_like(bank);frames=[];selected=np.zeros_like(bank);new=np.zeros_like(bank);proof=B/'restart2/bank-convex-source-saved-v1/projection.json';pins[str(proof)]=sha(proof);pr=json.loads(proof.read_text())
 for p in pr['protected_firsthits']:selected[p[1],p[0]]=True
 for x,y in pr['accepted_pixels']:selected[y,x]=True;new[y,x]=True
 for i,row in enumerate(animation['frames']):
  path=Path(row['image']);rawpath=Path(row['source']);assert sha(rawpath)==row['sha256'];pins[str(rawpath)]=sha(rawpath);pins[str(path)]=sha(path);image=Image.open(path).convert('RGBA');raw=np.array(Image.open(rawpath).convert('RGBA'));raw[np.all(raw[:,:,:3]==[0,251,0],axis=2)]=[0,0,0,0];assert np.array_equal(raw,np.array(image));canvas=Image.new('RGBA',src.size);canvas.paste(image,tuple(row['bbox'][:2]));a=np.array(canvas)[:,:,3]>0;union|=a;frames.append({'phase':i,'source':str(path),'source_sha256':sha(path),'raw_keyed_source_sha256':sha(rawpath),'normalization':'Exact green color-key removal; all non-key RGBA unchanged.','bbox':row['bbox'],'image_size':list(image.size),'delay':row['delay'],'alpha_pixels':int(a.sum()),'bank_overlap':int((bank&a).sum()),'projected_stone_overlap':int((selected&a).sum()),'new_stone_overlap':int((new&a).sum())})
 colors=np.array(src);colors[bank&union]=(colors[bank&union]*.4+np.array([0,210,255])*.6).astype('uint8');colors[wood&bank]=(colors[wood&bank]*.35+np.array([255,60,210])*.65).astype('uint8');box=(130,145,650,550);sheet=Image.new('RGB',(1040,435),'#222222');sheet.paste(src.crop(box),(0,30));sheet.paste(Image.fromarray(colors).crop(box),(520,30));draw=ImageDraw.Draw(sheet);draw.text((4,5),'Original source',fill='white');draw.text((524,5),'Cyan: actual all14 native alpha / magenta: woodmask18 overlap',fill='white');sheet.save(O/'source-context.png');Image.fromarray((bank&union).astype('uint8')*255).save(O/'native-foreground-reservation.png');Image.fromarray((selected&union).astype('uint8')*255).save(O/'stone-samples-with-foreground-crossings.png')
 report={'status':'EXACT_NATIVE_FOREGROUND_RESERVATIONS_NOT_ASSET_APPROVAL','pins':pins,'bank_domain_pixels':int(bank.sum()),'occupancy120_121_overlap':int((bank&occupancy).sum()),'woodmask18_overlap':int((bank&wood).sum()),'actual_alpha_union_bank_overlap':int((bank&union).sum()),'selected_stone_union_overlap':int((selected&union).sum()),'new_stone_union_overlap':int((new&union).sum()),'frames':frames,'native_sprite':animation['sprite'],'native_display_polyline':animation['display_polyline'],'tree18_source_context':{'woodmask':18,'native_obstacles':[33,34],'status':'Catalog association; complete crown physical ownership and source-material split not established by this audit.'},'limits':['Occupancy is not source RGBA or a material label. Exact animation PNG alpha is audited separately.','These native foreground pixels must remain with their existing observed owner; do not convert them into bank rock or duplicate the animation.','Crossing a stone sample does not prove the base rock RGB is wrong: native foreground precedence and artwork-state provenance need separate review. No samples reassigned or deleted.','Prior scoped context includes Tree01-03 but omits this major foreground; therefore it is not complete whole-bank appearance or runtime proof.','No geometry, source RGBA, runtime or canonical file changed.']};(O/'receipt.json').write_text(json.dumps(report,indent=2)+'\n');print({k:v for k,v in report.items()if k.endswith('overlap')or k=='bank_domain_pixels'})
if __name__=='__main__':main()
